def ranked_to_mode(apps, schema_editor):
    """Las listas numeradas pasan a ser del tipo «numerada», y los juegos que ya tenían, a haberlos añadido su dueño."""
    GameList = apps.get_model("lists", "GameList")
    ListItem = apps.get_model("lists", "ListItem")
    GameList.objects.filter(is_ranked=True).update(mode="ranked")
    for game_list in GameList.objects.all():
        ListItem.objects.filter(game_list=game_list, added_by__isnull=True).update(added_by=game_list.user_id)


def mode_to_ranked(apps, schema_editor):
    """Al deshacer la migración, las listas numeradas vuelven a tener is_ranked (las tier lists pasan a ser listas sin más)."""
    GameList = apps.get_model("lists", "GameList")
    GameList.objects.filter(mode="ranked").update(is_ranked=True)


